'''Short public pages; comprehensive unlisted reference generated from shared facts.'''
import json
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CATALOG=json.loads((ROOT/'content/catalog.json').read_text())
FAQ=json.loads((ROOT/'content/faq.json').read_text())
KNOWLEDGE_FAQ=json.loads((ROOT/'content/knowledge-faq.json').read_text())

def section(title,text):
    return f'<section class="section wrap prose"><h2>{title}</h2>{text}</section>'

def custom_pages(intro,cta):
    cards=[]
    for p in json.loads((ROOT/'content/packages.json').read_text()):
        extra='<li>Quarterly search &amp; AI visibility summary</li>' if p['name']=='Growth' else ''
        cards.append(f'''<article class="price-card"><p class="eyebrow">{p['name']}</p><h2>${p['development']:,}<span> to build</span></h2><p class="monthly">+ ${p['monthly']}<span> / month</span></p><p>{'A focused home for your business.' if p['name']=='Essential' else 'More room for your services and expertise.'}</p><ul><li>Up to {p['pages']} custom pages</li><li>{p['edits']} minor update{'s' if p['edits']>1 else ''} per month</li>{extra}<li>Own your site after development is paid</li></ul><a class="button" href="/contact/?plan={p['name'].lower()}">Talk about {p['name']} ↗</a></article>''')
    e=next(i for i in CATALOG['items'] if i['id']=='enterprise')
    cards.append(f'''<article class="price-card enterprise-card"><p class="eyebrow">Enterprise</p><h2>${e['monthly']}<span> / month</span></h2><p class="monthly">For 12 months · $4,800 total</p><p>Your custom website, spread over a year.</p><ul><li>Development, hosting, and agreed support</li><li>Build scope agreed before starting</li><li>Own your site after all 12 payments</li><li>Hosting/support after year one quoted separately</li></ul><a class="button" href="/contact/?plan=enterprise">Talk about Enterprise ↗</a></article>''')
    websites=intro('Websites & pricing','A website that<br>earns its place.','Explain your business. Help your customers. Make the next step easy.')
    websites+='<section class="wrap pricing-section"><div class="prices">'+''.join(cards)+'</div><p class="shared-inclusions">Every website includes mobile-friendly design, a standard contact form, basic search setup, hosting, and basic monitoring.</p><p class="fine">Essential &amp; Growth: 50% to start, 50% on completion; hosting is month-to-month after development is paid. Enterprise: 12-month commitment, billed from kickoff.</p></section>'
    websites+=section('What do you need it to do?','<p>Staff editing, bookings, business email, payments, or an online store? Tell us what would help your business. We’ll put the right capabilities into one proposal with a setup total and a monthly total.</p><p>Standard tools are included within the agreed limits. Advertising spend, payment processing, taxes, and exceptional purchases are identified separately when applicable.</p><p>You supply final content, images, and branding. Extra work is $75/hour, with a $37.50 minimum and prior agreement.</p><a class="text-link" href="/faq/">Questions about ownership, updates, or support? ↗</a>')+cta()
    about=intro('About Think Marketing','Good websites start<br>with good questions.','I’m Jacob. I build custom websites and help small and medium-sized businesses make practical marketing decisions. Think Marketing is based in Bend, Oregon.')
    about+=section('Your domain is the land.','<p>A domain gives you a place to build. What belongs there depends on your vision: a home for your expertise, a place to book appointments, or a tool that makes daily work easier.</p><p>Think Marketing helps bridge that starting point and what you want to create.</p>')
    about+='<section class="section wrap simple-questions"><h2>Two questions guide my work.</h2><div><h3>Is your website an expert on what you do?</h3><p>It should explain your services and answer the questions your customers ask.</p></div><div><h3>Is your website your most valuable employee?</h3><p>That’s the goal: a website that helps customers and takes useful work off your plate.</p></div></section>'
    about+=section('Let’s start with your business.','<p>Tell me what you do, who you serve, and what you want to improve. We’ll work out a sensible next step together.</p><a class="text-link" href="/contact/">Start a conversation ↗</a>')
    faq=intro('FAQ','A few straight answers.','The practical details, when you need them.')
    faq+='<section class="section wrap faq" aria-label="Frequently asked questions">'+''.join(f'<details id="question-{n+1}"><summary>{escape(f["question"])}</summary><p>{f["answer"]}</p></details>' for n,f in enumerate(FAQ))+'</section>'+cta()
    marketing=intro('Marketing','Start with<br>customer intent.','What is your customer trying to do—and where do they need help? That’s where our marketing work begins.')
    marketing+=section('Reach people with a reason to care.','<p>We build around the services people are looking for, the places you actually serve, and the next step they need to take. The goal is relevant inquiries from people your business can help.</p><p>Search terms, geography, and useful landing pages give the work direction. We focus on that fit rather than broad exposure for its own sake.</p>')
    marketing+='<section class="section wrap intent-services"><article id="consulting"><h2>Find your direction.</h2><p>Consulting helps you choose where to focus and how to use your budget. Start with a 60-minute conversation for $125.</p></article><article id="visibility"><h2>Be there when people look.</h2><p>Local SEO connects your services and location. AI/search visibility helps your expertise be found and understood. We bring the overlapping work into one plan.</p><p><a href="/local-seo/">Local SEO ↗</a> <a href="/ai-search-visibility/">AI &amp; search visibility ↗</a></p></article><article id="paid-search"><h2>Put intent to work.</h2><p>Google Search campaigns focus on relevant searches and your service area, then guide people to a useful next step.</p><p>$500 setup + $350/month management for up to two campaigns and $2,500/month ad spend. Ad spend is paid separately to Google.</p></article></section>'
    marketing+=section('Measure what helps the business.','<p>Where data is available, we look at calls, inquiries, and customer actions. You’ll know what we’re working on and what we can learn from it. Rankings and results aren’t guaranteed.</p>')+cta()
    local=intro('Marketing · Local SEO','Help nearby customers<br>find you.','Clear services, accurate business details, and the right geography. A useful local presence starts there.')
    local+=section('Match the search to your business.','<p>We review your Google Business Profile, business listings, and website around what customers need and where you work. Service information, hours, contact details, and the next step should agree.</p><p>Google Business Profile creation assistance is $200 for one profile. You keep control of the account; Google handles eligibility and verification. Existing-profile improvements and ongoing work receive a separate quote.</p>')
    local+=section('One connected presence.','<p>Local SEO and AI/search visibility share the same foundations: accurate information and useful answers. We identify the gaps and scope shared work once.</p><p>Reviews displays and genuine review-request workflows can be scoped. Review writing and response management are outside our services.</p><p><a href="/marketing/">Our approach to marketing</a> · <a href="/ai-search-visibility/">Explore the visibility review</a></p>')+cta()
    ai=intro('Marketing · AI & search visibility','Make your expertise<br>easier to find.','Help people—and the search services they use—understand what your business does and who it helps.')
    ai+=section('Start with a clear picture.','<p>The $350 Search &amp; AI Visibility Review covers up to 10 website pages and five customer questions sampled across two agreed AI services. You receive a plain-English report and prioritized next steps.</p><p>We check page access, discovery signals, and whether your information answers useful customer questions. Findings include sources, dates, and limitations. Implementation is quoted separately.</p>')
    ai+=section('Useful information. Measured observations.','<p>We work from existing and client-supplied material. No special formula can guarantee a ranking or AI recommendation; sampled answers can change over time.</p><p>Growth’s quarterly visibility summary is a brief check of available information, not the full $350 review or ongoing SEO implementation.</p><p><a href="/marketing/">Our approach to marketing</a> · <a href="/local-seo/">Explore local SEO</a></p>')+cta()
    # Unlisted, static HTML: readable without JavaScript by a future assistant.
    reference=intro('Assistant reference · '+CATALOG['version'],'Think Marketing:<br>complete service reference.','Business facts, philosophy, prices, scope, terms, and estimate rules. This page is not linked from the customer site. No live assistant is connected.')
    reference+='<section class="section wrap reference-body"><nav class="reference-toc" aria-label="Reference contents"><a href="#business-facts">Business &amp; approach</a><a href="#catalog">Full service catalog</a><a href="#policies">Terms &amp; policies</a><a href="#estimating">Estimate rules</a><a href="#reference-faq">Detailed answers</a></nav><section id="business-facts"><h2>Business facts &amp; approach</h2><p>Think Marketing · Bend, Oregon · Serving small and medium-sized businesses in Central Oregon. Contact Jacob through thinkmarketingbend@gmail.com or (541) 316-0735. Core services: custom websites, marketing consulting, local SEO, search/AI visibility, and Google Search PPC.</p><p>A domain is like a plot of land; Think Marketing bridges the starting point and the customer’s vision. Two guiding questions: is the website an expert on what the business does, and is it the business’s most valuable employee? These are design goals, not performance guarantees.</p><p>Marketing starts with customer intent: what people need, which services fit, where the business operates, relevant searches, and useful next steps. Geography and inquiry quality shape the plan. Local SEO and AI/search visibility overlap and are scoped together where useful. No general content production or review responses. Campaign ad text is included in PPC.</p><p>Current interface status: no public Jasper chat, guided assistant, or estimate builder is active. A future assistant must be explicitly configured to fetch this reference; publishing a page does not connect or train an AI.</p></section><section id="catalog"><h2>Full service catalog</h2><p>All amounts USD. Monthly fees include standard tools and infrastructure within stated limits. Feature add-ons are additional to base website hosting unless specified. Fixed menu amounts support informational estimates; project feasibility and delivery must be confirmed. “From” amounts are lower bounds, never fixed quotes.</p><p><a href="/estimate-reference/catalog.json">Machine-readable pricing catalog</a> · <a href="/estimate-reference/faq.json">Detailed FAQ data</a> · <a href="/estimate-reference/estimator.mjs">Deterministic estimate arithmetic</a></p><div class="reference-list">'
    for item in CATALOG['items']:
        prefix='From ' if item['price_kind']=='from' else ''
        extra=f' First {item["unit"]} setup ${item["setup"]}; each additional {item["unit"]} setup ${item["additional_setup"]}.' if item['additional_setup'] is not None else ''
        reference+=f'<article id="service-{escape(item["id"])}"><h3>{escape(item["name"])}</h3><p><strong>{prefix}${item["setup"]:,} setup / one-time + {prefix if item["monthly"] else ""}${item["monthly"]:,}/month</strong> · per {escape(item["unit"])}</p><p>{escape(item["scope"])}{escape(extra)}</p><p class="fine">Service ID: {escape(item["id"])} · {escape(item["delivery"])}</p></article>'
    reference+='</div></section><section id="policies"><h2>Terms &amp; policies</h2>'
    for key,val in CATALOG['rules'].items():
        if isinstance(val,list): val='; '.join(val)
        reference+=f'<h3>{escape(key.replace("_"," ").title())}</h3><p>{escape(str(val))}</p>'
    reference+='</section><section id="estimating"><h2>Estimate rules &amp; clarification questions</h2><ol><li>Determine whether this is a new website, an existing website improvement, or standalone business tools. Choose at most one website package. Existing hosting suitability must be confirmed.</li><li>Count independent licensed inboxes separately from aliases. Ordinary calendars come with email; public appointment booking is a separate capability. Ask about migration, team routing, payments, and SMS.</li><li>Ask what staff need to edit. Basic admin is one content area with five agreed fields, not customer/order/inventory software.</li><li>Confirm which domains are additional, their actual names, renewal eligibility, new purchase versus transfer, and redirect versus separate website. Domain ownership stays with the customer.</li><li>Calculate first-seat setup plus additional-seat setup where listed. Multiply monthly unit price by quantity. Use catalog values and deterministic arithmetic; never invent a price.</li><li>Enterprise is $400/month for 12 months, $4,800 total, billed from kickoff. Ownership follows all 12 payments. Do not imply the $400 continues after year one or that post-term hosting is free. Optional selected add-ons are additional.</li><li>Avoid duplicate fees: Local SEO includes its defined profile maintenance and monitoring; PPC includes campaign conversion setup; the same workflow is not both a CRM connection and a separate automation. GBP setup and a qualifying review may remove corresponding onboarding after owner confirmation. Transfers replace overlapping domain setup. Confirm which sites/locations overlap.</li><li>Only the owner approves discounts. Show list price and any approved setup discount separately. Scope exceeding listed limits requires an agreed bundled quote before charges increase.</li><li>Return itemized setup and monthly totals, applicable exclusions, assumptions, term, and unresolved questions. Estimates are valid 30 days and require human scope/availability confirmation. A from-price produces a starting estimate.</li><li>Do not invent launch dates, results, supplier capabilities, case studies, rankings, AI recommendations, legal terms, or availability. Refer unknowns to Think Marketing. No purchasing, messaging, contract acceptance, or account changes are authorized by an estimate request.</li></ol><h3>Worked example: existing website</h3><p>Three new staff inboxes without migration: $200 setup + $60/month. Three public booking seats: $400 setup + $105/month. One basic admin: $750 setup + $65/month. Two additional eligible managed domains: $150 setup + $10/month. Total: $1,500 setup + $240/month, excluding existing website hosting and taxes. Standard tools within stated limits included.</p><p>Add Essential: $3,495 setup + $290/month. If the staff only need the ordinary calendars included with their inboxes, remove public scheduling: $1,100 setup + $135/month before website hosting. No discounts assumed.</p></section><section id="reference-faq"><h2>Detailed customer answers</h2>'
    for f in KNOWLEDGE_FAQ:
        reference+=f'<h3>{escape(f["question"])}</h3><p>{f["answer"]}</p>'
    reference+='</section><p class="fine">Reference version '+escape(CATALOG['version'])+'. Noindex is a search-engine request, not access control. Anyone with this URL can read it. No private customer data, supplier costs, credentials, or margins belong in this reference.</p></section>'
    return {'websites':('Website pricing',websites),'about':('About Think Marketing',about),'faq':('Frequently asked questions',faq),'marketing':('Marketing services',marketing),'local-seo':('Local SEO',local),'ai-search-visibility':('AI & search visibility',ai),'estimate-reference':('Assistant reference',reference)}
